# component runtime
js=r'''window.NexCreatorModules=(()=>{
 const registry=window.NEX_CREATOR_MODULES||[],q=v=>typeof v==='string'?document.querySelector(v):v,esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
 const getDef=v=>typeof v==='object'&&v.id?v:registry.find(x=>x.id===v||x.slug===v);const clamp=(n,a,b)=>Math.max(a,Math.min(b,Number(n)||0));
 const demo={avatar:'assets/media/photo-creator.svg',media:'assets/media/website-screenshot.svg',product:'assets/media/photo-product.svg'};
 const defaults={style:'clean-editorial',energy:'medium',duration:1.8,contentLength:'medium',title:'Creator module',caption:'Replaceable creator content.',handle:'@creator',date:'Today',avatar:demo.avatar,media:demo.media,logoSrc:'',items:[]};
 const img=(src,alt='Replaceable media')=>src?`<img src="${esc(src)}" alt="${esc(alt)}">`:`<span class="cm-placeholder">MEDIA</span>`;
 const avatar=c=>`<div class="cm-avatar">${img(c.avatar,c.title)}</div>`;const logo=c=>c.logoSrc?`<img class="cm-logo" src="${esc(c.logoSrc)}" alt="Authorized brand logo">`:`<div class="cm-logo cm-logo-fallback">NS</div>`;
 const head=c=>`<div class="cm-head">${avatar(c)}<div><strong data-fit>${esc(c.title)}</strong><small data-fit>${esc(c.handle||c.date||'')}</small></div></div>`;
 const metric=(label,value,change)=>`<article class="cm-metric"><small>${esc(label)}</small><strong data-count="${Number(value)||0}">0</strong><em class="${Number(change)<0?'negative':'positive'}">${Number(change)>0?'+':''}${Number(change||0)}%</em></article>`;
 const buttons=(items)=>`<div class="cm-link-list">${items.map((x,i)=>`<button><b>${String(i+1).padStart(2,'0')}</b><span>${esc(typeof x==='string'?x:x.text||x.label)}</span><i>↗</i></button>`).join('')}</div>`;
 function render(def,c){const items=c.items||[];switch(def.slug){
 case'social-post':return `${head(c)}<div class="cm-media">${img(c.media,c.caption)}</div><p data-fit>${esc(c.caption)}</p><div class="cm-actions"><span>♥ ${c.counts?.likes||2840}</span><span>◌ ${c.counts?.comments||184}</span><span>↗ ${c.counts?.shares||96}</span><small>${esc(c.date)}</small></div>`;
 case'thread':return `${head(c)}<h3 data-fit>${esc(c.title)}</h3><ol class="cm-thread">${items.map((x,i)=>`<li><b>${i+1}</b><span data-fit>${esc(x)}</span></li>`).join('')}</ol>`;
 case'comment-exchange':return `<h3>${esc(c.title)}</h3><div class="cm-comments">${items.map((x,i)=>`<article class="${i%2?'mine':''}"><b>${esc(x.author)}</b><p data-fit>${esc(x.text)}</p></article>`).join('')}</div>`;
 case'creator-profile':return `<div class="cm-profile-hero">${avatar(c)}<div><h2 data-fit>${esc(c.title)}</h2><b>${esc(c.handle)}</b><p data-fit>${esc(c.body||c.caption)}</p></div></div><div class="cm-profile-links"><span>VIDEOS</span><span>NEWSLETTER</span><span>WORKSHOPS</span></div>`;
 case'subscriber-counter':case'view-counter':return `<div class="cm-counter-icon" data-icon="${def.slug==='subscriber-counter'?'subscriber':'view-count'}"></div><small>${esc(c.title)}</small><strong class="cm-big-count" data-count="${Number(c.value)||0}">0</strong><em>+${Number(c.change||0)}%</em>`;
 case'engagement-summary':case'campaign-result':case'affiliate-result':return `<h3>${esc(c.title)}</h3><div class="cm-metrics">${items.map(x=>metric(x.label,x.value,x.change)).join('')}</div>`;
 case'content-calendar':return `<h3>${esc(c.title)}</h3><div class="cm-calendar">${items.map(x=>`<article><b>${esc(x.label)}</b><span data-fit>${esc(x.text)}</span></article>`).join('')}</div>`;
 case'publishing-checklist':return `<h3>${esc(c.title)}</h3><ul class="cm-checklist">${items.map(x=>`<li class="${x.done?'done':''}"><i>${x.done?'✓':'○'}</i><span>${esc(x.text)}</span></li>`).join('')}</ul>`;
 case'thumbnail-selector':return `<h3>${esc(c.title)}</h3><div class="cm-thumbs">${items.map((x,i)=>`<article class="${i==c.selected?'selected':''}"><div>${img(c.media,x)}</div><b data-fit>${esc(x)}</b><span>${i==c.selected?'SELECTED':'OPTION '+(i+1)}</span></article>`).join('')}</div>`;
 case'video-chapters':return `<h3>${esc(c.title)}</h3><ol class="cm-chapters">${items.map(x=>`<li><b>${esc(x.time)}</b><span data-fit>${esc(x.text)}</span><i></i></li>`).join('')}</ol>`;
 case'newsletter-card':return `<div class="cm-publish-icon" data-icon="newsletter"></div><small>${esc(c.handle)}</small><h2 data-fit>${esc(c.title)}</h2><p data-fit>${esc(c.caption)}</p><button>READ THE LATEST ISSUE</button>`;
 case'podcast-episode':return `<div class="cm-podcast-art">${img(c.media,c.title)}<span>▶</span></div><div><small>${esc(c.handle)}</small><h2 data-fit>${esc(c.title)}</h2><p data-fit>${esc(c.caption)}</p><div class="cm-wave">${Array.from({length:18},(_,i)=>`<i style="height:${12+(i*17)%34}px"></i>`).join('')}</div></div>`;
 case'blog-article':return `<div class="cm-article-media">${img(c.media,c.title)}</div><small>${esc(c.handle)}</small><h2 data-fit>${esc(c.title)}</h2><p data-fit>${esc(c.caption)}</p>`;
 case'community-poll':case'reaction-panel':return `<h3>${esc(c.title)}</h3><div class="cm-poll">${items.map((x,i)=>`<article><div><b>${esc(x.label)}</b><span>${x.value}%</span></div><i style="--value:${clamp(x.value,0,100)}%"></i></article>`).join('')}</div>`;
 case'question-and-answer-card':return `<div class="cm-qa"><b>Q</b><h2 data-fit>${esc(c.title)}</h2><b>A</b><p data-fit>${esc(c.caption)}</p></div>`;
 case'testimonial':case'review':return `<div class="cm-quote">“</div><p class="cm-quote-copy" data-fit>${esc(c.caption)}</p><div class="cm-proof-foot">${avatar(c)}<div><b>${esc(c.title)}</b><small>${esc(c.handle)}</small></div>${def.slug==='review'?`<strong>★ ${c.value||4.9}</strong>`:''}</div>`;
 case'user-generated-content-frame':return `${head(c)}<div class="cm-media">${img(c.media,c.caption)}</div><p data-fit>${esc(c.caption)}</p><span class="cm-ugc-label">COMMUNITY FEATURE</span>`;
 case'creator-collaboration':return `<div class="cm-collab"><div>${avatar(c)}<b>${esc(c.title.split('×')[0]||'Creator')}</b></div><span>×</span><div>${avatar({...c,avatar:c.media})}<b>${esc(c.title.split('×')[1]||'Creator')}</b></div></div><p data-fit>${esc(c.caption)}</p><small>${esc(c.handle)}</small>`;
 case'sponsorship-card':return `${logo(c)}<small>${esc(c.handle)}</small><h2 data-fit>${esc(c.title)}</h2><p data-fit>${esc(c.caption)}</p><span class="cm-sponsored">SPONSORED SEGMENT</span>`;
 case'brand-partnership':return `<div class="cm-partner-lockup"><div class="cm-creator-mark">MC</div><span>×</span>${logo(c)}</div><h2 data-fit>${esc(c.title)}</h2><p data-fit>${esc(c.caption)}</p><small>${esc(c.handle)}</small>`;
 case'link-in-bio-screen':return `${head(c)}${buttons(items)}`;
 case'call-to-follow':case'call-to-subscribe':return `<div class="cm-action-icon" data-icon="${def.slug==='call-to-follow'?'subscriber':'newsletter'}"></div><h2 data-fit>${esc(c.title)}</h2><p data-fit>${esc(c.caption)}</p><button>${def.slug==='call-to-follow'?'FOLLOW':'SUBSCRIBE'}</button><small>${esc(c.handle)}</small>`;
 default:return `<h2>${esc(c.title)}</h2><p>${esc(c.caption)}</p>`}
 }
 function mountLower(el,c){el.querySelectorAll('[data-icon]').forEach(slot=>{if(window.NexCreatorIcons){const icon=NexCreatorIcons.create('icon.creator.'+slot.dataset.icon+'.paper-01',{size:70,state:'active',treatment:'paper-cutout'});slot.append(icon)}})}
 function fitText(el){el.querySelectorAll('[data-fit]').forEach(n=>{n.style.fontSize='';n.style.overflowWrap='anywhere';let g=0;while((n.scrollWidth>n.clientWidth+2||n.scrollHeight>n.clientHeight+2)&&g<50){let s=parseFloat(getComputedStyle(n).fontSize)||14;if(s<=8)break;n.style.fontSize=(s-.4)+'px';g++}});return el}
 function create(defOrId,config={}){const def=getDef(defOrId);if(!def)throw Error('Unknown creator module '+defOrId);const c={...defaults,...JSON.parse(JSON.stringify(def.sampleConfig||{})),...config};if(c.contentLength==='short'){c.caption=String(c.caption||'').slice(0,90);c.items=(c.items||[]).slice(0,3)}if(c.contentLength==='long'){c.caption=(c.caption||'')+' '+(c.longExtra||'Additional context remains editable and safely fitted inside the component.');}
 const el=document.createElement('section');el.className=`nex-creator-module module-${def.slug}`;el.dataset.componentId=def.id;el.dataset.slug=def.slug;el.dataset.style=c.style;el.dataset.energy=c.energy;el.dataset.contentLength=c.contentLength;el.setAttribute('role','group');el.setAttribute('aria-label',def.accessibilityLabel);el.__moduleConfig=c;el.innerHTML=`<div class="cm-shell"><div class="cm-content">${render(def,c)}</div><div class="cm-grain"></div></div>`;mountLower(el,c);requestAnimationFrame(()=>fitText(el));return el}
 function animate(target,config={}){const el=q(target),d=Number(config.duration||el?.__moduleConfig?.duration||1.8),energy=config.energy||el?.dataset.energy||'medium',amp={low:.7,medium:1,high:1.3}[energy]||1,motion=config.motion||'paper-slide';if(!el)throw Error('Creator module target missing');const shell=el.querySelector('.cm-shell'),tl=NexMotion.createTimeline({defaults:{ease:'power3.out'}});if(motion==='cut-paper-pop')tl.fromTo(shell,{scale:.7,rotation:-3*amp,opacity:0},{scale:1,rotation:0,opacity:1,duration:d*.45,ease:'back.out(1.7)'},0);else if(motion==='drop-and-settle')tl.fromTo(shell,{y:-80*amp,rotation:5*amp,opacity:0},{y:0,rotation:0,opacity:1,duration:d*.48,ease:'bounce.out'},0);else if(motion==='unfold')tl.fromTo(shell,{scaleY:.08,rotationX:68,opacity:0,transformOrigin:'50% 0%'},{scaleY:1,rotationX:0,opacity:1,duration:d*.5,ease:'power3.out'},0);else tl.fromTo(shell,{x:-70*amp,y:12,opacity:0},{x:0,y:0,opacity:1,duration:d*.45,ease:'power3.out'},0);
 const pieces=[...el.querySelectorAll('.cm-content>*')];pieces.forEach((x,i)=>tl.fromTo(x,{y:18+(i%3)*6,opacity:0,scale:.97},{y:0,opacity:1,scale:1,duration:d*.26,ease:i%2?'back.out(1.4)':'power2.out'},.25+i*.075));el.querySelectorAll('[data-count]').forEach((n,i)=>{const to=Number(n.dataset.count)||0;tl.addUpdate(.35+i*.08,d*.45,p=>n.textContent=Intl.NumberFormat(undefined,{notation:to>9999?'compact':'standard',maximumFractionDigits:1}).format(Math.round(to*p)),'power3.out')});el.querySelectorAll('.cm-poll i').forEach((n,i)=>tl.fromTo(n,{scaleX:0},{scaleX:1,duration:d*.34,ease:'power3.out'},.42+i*.08));el.querySelectorAll('.cm-checklist li').forEach((n,i)=>tl.fromTo(n,{x:-24,opacity:0},{x:0,opacity:1,duration:d*.25},.35+i*.1));tl.fromTo(shell,{y:0},{y:-3*amp,duration:.8,ease:'sine.inOut',repeat:2,yoyo:true},Math.max(.9,d*.75));tl.seek(0);el.__tl=tl;return tl}
 function update(target,config={}){const el=q(target),next=create(el.dataset.componentId,{...el.__moduleConfig,...config});el.replaceWith(next);return next}
 return{registry,getDef,create,animate,update,fitText};})();'''
(root/'components/creator-modules.js').write_text(js)
# CSS
css=r'''.nex-creator-module{--cm-w:500px;--cm-h:380px;position:relative;width:var(--cm-w);height:var(--cm-h);container-type:size;isolation:isolate;font-variant-numeric:tabular-nums;transform-origin:center;color:var(--ink)}.cm-shell{position:absolute;inset:2%;background:var(--paper-surface);border:var(--outline-width) solid var(--ink);border-radius:var(--paper-radius);box-shadow:10px 12px 0 color-mix(in srgb,var(--shadow-color) 24%,transparent),0 22px 30px color-mix(in srgb,var(--shadow-color) 18%,transparent);padding:7%;overflow:hidden;will-change:transform,opacity}.cm-shell:before{content:"";position:absolute;width:86px;height:24px;left:50%;top:-8px;transform:translateX(-50%) rotate(-2deg);background:color-mix(in srgb,var(--secondary) 64%,transparent);border:1px solid color-mix(in srgb,var(--ink) 25%,transparent);z-index:7}.cm-content{height:100%;position:relative;z-index:2;display:flex;flex-direction:column;gap:clamp(7px,2.2cqw,13px);min-width:0}.cm-grain{position:absolute;inset:0;pointer-events:none;opacity:var(--grain-opacity);mix-blend-mode:multiply;background-image:radial-gradient(circle at 30% 40%,rgba(0,0,0,.5) 0 .5px,transparent .7px),repeating-linear-gradient(93deg,transparent 0 8px,rgba(255,255,255,.6) 9px 10px,transparent 11px 17px);background-size:12px 14px,20px 22px}.nex-creator-module[data-style="handmade-scrapbook"] .cm-shell{clip-path:polygon(0 3%,8% 0,16% 2%,25% 0,35% 2%,46% 0,56% 2%,68% 0,79% 2%,90% 0,100% 3%,98% 16%,100% 31%,98% 47%,100% 62%,98% 79%,100% 100%,84% 98%,69% 100%,51% 98%,34% 100%,16% 98%,0 100%,2% 82%,0 65%,2% 49%,0 32%,2% 16%)}.nex-creator-module[data-style="technical-notebook"] .cm-shell{background-color:var(--paper-surface);background-image:linear-gradient(color-mix(in srgb,var(--primary) 10%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--primary) 10%,transparent) 1px,transparent 1px);background-size:22px 22px}.nex-creator-module[data-style="bold-paper-collage"] .cm-shell{border-width:5px;box-shadow:14px 14px 0 var(--primary)}.cm-content h2,.cm-content h3,.cm-content p{margin:0}.cm-content h2{font:900 clamp(24px,7.5cqw,44px)/.92 var(--display-font);letter-spacing:-.05em;text-transform:uppercase}.cm-content h3{font:900 clamp(18px,5.3cqw,30px)/.95 var(--display-font);text-transform:uppercase}.cm-content p{font:700 clamp(10px,2.8cqw,15px)/1.2 var(--ui-font)}.cm-content small{font:800 clamp(7px,1.9cqw,10px)/1 var(--mono-font);color:var(--primary);text-transform:uppercase}.cm-head{display:flex;align-items:center;gap:10px}.cm-head strong{font:900 clamp(12px,3.3cqw,18px) var(--display-font)}.cm-head small{display:block;margin-top:3px}.cm-avatar{width:54px;height:54px;border:3px solid var(--ink);border-radius:50%;overflow:hidden;flex:none;background:var(--secondary)}.cm-avatar img,.cm-media img,.cm-media video,.cm-podcast-art img,.cm-article-media img{width:100%;height:100%;object-fit:cover;display:block}.cm-media{flex:1;min-height:0;border:3px solid var(--ink);overflow:hidden;background:var(--paper-surface-alt)}.cm-actions{display:flex;gap:12px;align-items:center;font:800 clamp(7px,1.8cqw,10px) var(--mono-font)}.cm-actions small{margin-left:auto}.cm-thread,.cm-chapters,.cm-checklist{list-style:none;padding:0;margin:0;display:grid;gap:7px;min-height:0}.cm-thread li{display:grid;grid-template-columns:30px 1fr;gap:8px;align-items:center;border:2px solid var(--ink);padding:7px;background:var(--paper-surface-alt)}.cm-thread b{display:grid;place-items:center;width:25px;height:25px;border-radius:50%;background:var(--accent);border:2px solid var(--ink);font:900 10px var(--mono-font)}.cm-thread span{font:700 clamp(8px,2cqw,11px) var(--ui-font)}.cm-comments{display:flex;flex-direction:column;gap:8px;overflow:hidden}.cm-comments article{width:83%;border:2px solid var(--ink);background:var(--paper-surface-alt);padding:8px 10px;border-radius:14px 14px 14px 2px}.cm-comments article.mine{margin-left:auto;background:var(--highlight);border-radius:14px 14px 2px 14px}.cm-comments b{font:900 10px var(--mono-font)}.cm-comments p{font-size:11px}.cm-profile-hero{display:grid;grid-template-columns:110px 1fr;gap:18px;align-items:center}.cm-profile-hero .cm-avatar{width:110px;height:110px}.cm-profile-hero b{font:900 12px var(--mono-font);color:var(--primary)}.cm-profile-links{margin-top:auto;display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.cm-profile-links span{border:2px solid var(--ink);padding:8px;text-align:center;font:900 8px var(--mono-font);background:var(--paper-surface-alt)}.module-subscriber-counter .cm-content,.module-view-counter .cm-content{justify-content:center;align-items:center;text-align:center}.cm-counter-icon .nex-creator-icon,.cm-publish-icon .nex-creator-icon,.cm-action-icon .nex-creator-icon{width:76px!important;height:76px!important}.cm-big-count{font:900 clamp(54px,20cqw,105px)/.8 var(--display-font);letter-spacing:-.08em}.module-subscriber-counter em,.module-view-counter em{font:900 14px var(--mono-font);color:#187840}.cm-metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;flex:1}.cm-metric{border:2px solid var(--ink);background:var(--paper-surface-alt);padding:10px;display:flex;flex-direction:column;justify-content:center;overflow:hidden}.cm-metric small{color:var(--ink-muted)}.cm-metric strong{font:900 clamp(21px,7cqw,38px) var(--display-font)}.cm-metric em{font:800 9px var(--mono-font);font-style:normal}.positive{color:#187840}.negative{color:#7a3d37}.cm-calendar{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;flex:1}.cm-calendar article{border:2px solid var(--ink);padding:6px;display:flex;flex-direction:column;gap:8px;background:var(--paper-surface-alt)}.cm-calendar b{font:900 9px var(--mono-font);color:var(--primary)}.cm-calendar span{font:800 clamp(8px,1.8cqw,10px) var(--ui-font);overflow-wrap:anywhere}.cm-checklist{margin-top:6px}.cm-checklist li{display:flex;gap:12px;align-items:center;border-bottom:2px solid var(--ink);padding:9px 4px;font:800 clamp(10px,2.6cqw,14px) var(--ui-font)}.cm-checklist i{width:28px;height:28px;display:grid;place-items:center;border:2px solid var(--ink);font-style:normal}.cm-checklist .done i{background:var(--primary);color:white}.cm-thumbs{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;flex:1;min-height:0}.cm-thumbs article{border:2px solid var(--ink);padding:5px;display:grid;grid-template-rows:1fr auto auto;gap:4px;min-width:0}.cm-thumbs article.selected{box-shadow:0 0 0 5px var(--accent)}.cm-thumbs article>div{min-height:0;overflow:hidden}.cm-thumbs img{width:100%;height:100%;object-fit:cover}.cm-thumbs b{font:900 clamp(8px,1.9cqw,11px)/1 var(--display-font);text-transform:uppercase}.cm-thumbs span{font:800 7px var(--mono-font);color:var(--primary)}.cm-chapters li{display:grid;grid-template-columns:46px 1fr 70px;align-items:center;gap:8px}.cm-chapters b{font:900 9px var(--mono-font);color:var(--primary)}.cm-chapters span{font:800 clamp(9px,2.2cqw,12px) var(--ui-font)}.cm-chapters i{height:6px;background:var(--paper-surface-alt);border:1px solid var(--ink)}.module-newsletter-card .cm-content,.module-call-to-follow .cm-content,.module-call-to-subscribe .cm-content{align-items:center;text-align:center;justify-content:center}.cm-content button{border:3px solid var(--ink);background:var(--accent);color:white;padding:10px 15px;font:900 10px var(--mono-font);box-shadow:4px 5px 0 var(--ink)}.module-podcast-episode .cm-content{display:grid;grid-template-columns:42% 1fr;align-items:center}.cm-podcast-art{position:relative;height:78%;border:4px solid var(--ink);overflow:hidden}.cm-podcast-art span{position:absolute;inset:auto auto 12px 12px;width:45px;height:45px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:white;border:3px solid var(--ink)}.cm-wave{display:flex;align-items:center;gap:3px;height:48px}.cm-wave i{width:4px;background:var(--primary);border-radius:4px}.cm-article-media{height:43%;border:3px solid var(--ink);overflow:hidden}.cm-poll{display:grid;gap:9px;flex:1}.cm-poll article div{display:flex;justify-content:space-between;font:800 10px var(--mono-font)}.cm-poll article>i{display:block;width:var(--value);height:12px;background:var(--primary);border:2px solid var(--ink);transform-origin:left}.cm-qa{display:grid;grid-template-columns:48px 1fr;gap:12px;align-items:start}.cm-qa>b{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:var(--accent);color:white;border:3px solid var(--ink);font:900 22px var(--display-font)}.cm-qa p{padding-top:8px}.cm-quote{font:900 80px/0 var(--display-font);color:var(--accent);margin-top:25px}.cm-quote-copy{font-size:clamp(17px,5cqw,28px)!important;line-height:1.1!important}.cm-proof-foot{margin-top:auto;display:flex;align-items:center;gap:10px}.cm-proof-foot>strong{margin-left:auto;font:900 25px var(--display-font);color:var(--primary)}.cm-ugc-label,.cm-sponsored{position:absolute;right:0;top:0;background:var(--accent);color:white;border:2px solid var(--ink);padding:5px 7px;font:900 7px var(--mono-font)}.cm-collab{display:grid;grid-template-columns:1fr 42px 1fr;align-items:center;text-align:center;gap:8px}.cm-collab>div{display:grid;justify-items:center;gap:8px}.cm-collab .cm-avatar{width:100px;height:100px}.cm-collab>span{font:900 36px var(--display-font);color:var(--accent)}.cm-logo,.cm-creator-mark{width:86px;height:62px;object-fit:contain;border:3px solid var(--ink);background:var(--paper-surface-alt);display:grid;place-items:center;font:900 28px var(--display-font)}.module-sponsorship-card .cm-content{justify-content:center}.cm-partner-lockup{display:flex;align-items:center;gap:18px}.cm-partner-lockup>span{font:900 34px var(--display-font)}.cm-link-list{display:grid;gap:8px;flex:1}.cm-link-list button{display:grid;grid-template-columns:28px 1fr 20px;align-items:center;text-align:left;background:var(--paper-surface-alt);color:var(--ink);padding:8px;box-shadow:3px 4px 0 var(--ink)}.cm-link-list b{color:var(--primary)}.cm-action-icon{min-height:78px}.cm-placeholder{display:grid;place-items:center;width:100%;height:100%;background:var(--paper-surface-alt);font:900 10px var(--mono-font)}
@media(max-width:700px){.nex-creator-module{--cm-w:360px;--cm-h:360px}.cm-shell{padding:8%}.cm-calendar{grid-template-columns:repeat(3,1fr)}.cm-thumbs{grid-template-columns:1fr}.cm-thumbs article{grid-template-columns:34% 1fr auto;grid-template-rows:1fr}.cm-profile-hero{grid-template-columns:82px 1fr}.cm-profile-hero .cm-avatar{width:82px;height:82px}}'''
(root/'styles/creator-modules.css').write_text(css)
# Explorer assets
(root/'styles/creator-module-explorer.css').write_text('''body{margin:0;background:var(--paper-bg);color:var(--ink);font-family:var(--ui-font)}.cm-explorer{display:grid;grid-template-columns:310px 1fr;min-height:100vh}.cm-side{padding:28px;background:var(--ink);color:white;position:sticky;top:0;height:100vh;overflow:auto}.cm-side h1{font:900 31px/.9 var(--display-font);margin:0 0 12px}.cm-side p{font:700 12px/1.4 var(--ui-font);opacity:.8}.cm-side label{display:grid;gap:6px;font:800 9px var(--mono-font);margin-top:15px}.cm-side input,.cm-side select,.cm-side textarea{padding:9px;border:2px solid white;background:#fff;color:#111;font:700 12px var(--ui-font)}.cm-side textarea{min-height:80px}.cm-side button{margin-top:16px;width:100%;padding:11px;border:2px solid white;background:var(--accent);color:white;font-weight:900}.cm-main{padding:30px}.cm-hero{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.cm-hero h2{font:900 clamp(38px,6vw,76px)/.86 var(--display-font);margin:0;letter-spacing:-.06em}.cm-count{font:900 32px var(--display-font);border:3px solid var(--ink);padding:8px 12px;background:var(--secondary)}.cm-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:20px}.cm-card{background:var(--paper-surface);border:3px solid var(--ink);padding:14px;box-shadow:7px 8px 0 rgba(0,0,0,.16);min-width:0}.cm-card-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.cm-card-head h3{font:900 18px var(--display-font);margin:0;text-transform:uppercase}.cm-card-head small{font:800 8px var(--mono-font);color:var(--primary)}.cm-mount{height:360px;display:grid;place-items:center;overflow:hidden;margin-top:12px;background:color-mix(in srgb,var(--paper-bg) 70%,white);border:1px dashed var(--ink)}.cm-mount .nex-creator-module{transform:scale(.72)}.cm-card-actions{display:flex;gap:7px;margin-top:10px}.cm-card-actions button{flex:1;border:2px solid var(--ink);background:var(--paper-surface-alt);padding:7px;font-weight:900}@media(max-width:900px){.cm-explorer{grid-template-columns:1fr}.cm-side{position:relative;height:auto}.cm-grid{grid-template-columns:1fr}}''')
explorer='''<!doctype html><html data-paper-style="clean-editorial"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Creator Module Explorer</title><link rel="stylesheet" href="styles/tokens.css"><link rel="stylesheet" href="styles/paper.css"><link rel="stylesheet" href="styles/icons.css"><link rel="stylesheet" href="styles/creator-icons.css"><link rel="stylesheet" href="styles/creator-modules.css"><link rel="stylesheet" href="styles/creator-module-explorer.css"></head><body><div class="cm-explorer"><aside class="cm-side"><h1>CREATOR MODULES</h1><p>Platform-neutral publishing systems composed from the approved paper, motion, media, icon and data foundations.</p><label>Search<input id="search" placeholder="Search modules or intents"></label><label>Paper style<select id="style"><option>clean-editorial</option><option>handmade-scrapbook</option><option>technical-notebook</option><option>bold-paper-collage</option></select></label><label>Palette<select id="palette"><option value="warm">Warm</option><option value="cobalt">Cobalt</option><option value="charcoal">Charcoal</option></select></label><label>Motion energy<select id="energy"><option>low</option><option selected>medium</option><option>high</option></select></label><label>Content state<select id="length"><option>short</option><option selected>medium</option><option>long</option></select></label><label>Handle<input id="handle" value="@mayamakes"></label><label>Caption<textarea id="caption">A reusable creator module with replaceable content and platform-neutral design.</textarea></label><button id="replay">Replay visible modules</button></aside><main class="cm-main"><header class="cm-hero"><div><small>BATCH 11 / CREATOR & SOCIAL PUBLISHING</small><h2>BUILT TO PUBLISH.</h2></div><div class="cm-count" id="count">28</div></header><section class="cm-grid" id="grid"></section></main></div><script src="vendor/gsap-compat.js"></script><script src="runtime/theme.js"></script><script src="runtime/motion-engine.js"></script><script src="runtime/creator-icon-registry.js"></script><script src="components/creator-icons.js"></script><script src="runtime/creator-module-registry.js"></script><script src="components/creator-modules.js"></script><script src="runtime/creator-module-explorer.js"></script></body></html>'''
(root/'creator-module-explorer.html').write_text(explorer)
explorer_js=r'''(()=>{const grid=document.querySelector('#grid');let records=[];function build(){grid.innerHTML='';records=NexCreatorModules.registry.map(def=>{const card=document.createElement('article');card.className='cm-card';card.dataset.search=(def.name+' '+def.keywords.join(' ')).toLowerCase();card.innerHTML=`<div class="cm-card-head"><h3>${def.name}</h3><small>${def.subtype}</small></div><div class="cm-mount"></div><div class="cm-card-actions"><button data-replay>Replay</button><button data-manifest>Manifest</button></div>`;const cfg={contentLength:length.value,style:style.value,energy:energy.value,handle:handle.value,caption:caption.value};let el=NexCreatorModules.create(def,cfg);card.querySelector('.cm-mount').append(el);const play=()=>{const tl=NexCreatorModules.animate(el,{energy:energy.value,duration:1.8});tl.restart()};card.querySelector('[data-replay]').onclick=play;card.querySelector('[data-manifest]').onclick=()=>alert(JSON.stringify(def,null,2));grid.append(card);return{def,card,get el(){return el},set el(v){el=v},play}});filter()}
 function refresh(){records.forEach(r=>{const next=NexCreatorModules.update(r.el,{contentLength:length.value,style:style.value,energy:energy.value,handle:handle.value,caption:caption.value});r.el=next;r.play()})}
 function filter(){const s=search.value.toLowerCase();let n=0;records.forEach(r=>{const show=!s||r.card.dataset.search.includes(s);r.card.hidden=!show;if(show)n++});count.textContent=n}
 search.oninput=filter;palette.onchange=()=>{NexTheme.applyPalette(palette.value);records.forEach(r=>r.play())};style.onchange=()=>{NexTheme.setStyle(style.value);refresh()};energy.onchange=refresh;length.onchange=refresh;handle.onchange=refresh;caption.onchange=refresh;replay.onclick=()=>records.filter(r=>!r.card.hidden).forEach(r=>r.play());NexTheme.applyPalette('warm');build();setTimeout(()=>records.slice(0,6).forEach(r=>r.play()),50)})();'''
(root/'runtime/creator-module-explorer.js').write_text(explorer_js)
# standalone previews inline with root scripts relative ../../
for i,m in enumerate(reg,1):
 slug=m['slug']; cfg=json.dumps(m['sampleConfig'])
 html=f'''<!doctype html><html data-paper-style="clean-editorial"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../../styles/tokens.css"><link rel="stylesheet" href="../../styles/paper.css"><link rel="stylesheet" href="../../styles/icons.css"><link rel="stylesheet" href="../../styles/creator-icons.css"><link rel="stylesheet" href="../../styles/creator-modules.css"><style>body{{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--paper-bg)}}</style><title>{m['name']}</title></head><body><main id="mount"></main><script src="../../vendor/gsap-compat.js"></script><script src="../../runtime/theme.js"></script><script src="../../runtime/motion-engine.js"></script><script src="../../runtime/creator-icon-registry.js"></script><script src="../../components/creator-icons.js"></script><script src="../../runtime/creator-module-registry.js"></script><script src="../../components/creator-modules.js"></script><script>NexTheme.applyPalette('warm');const el=NexCreatorModules.create('{m['id']}',{cfg});mount.append(el);const tl=NexCreatorModules.animate(el,{{duration:1.8}});window.__timelines={{'{m['id']}':tl}};window.seekComposition=t=>tl.seek(t);tl.seek(0);</script></body></html>'''
 (pdir/f'{i:02d}-{slug}.html').write_text(html)
# scene styles
(root/'styles/creator-module-scenes.css').write_text('''.creator-module-scene{width:100vw;height:100vh;background:var(--paper-bg);color:var(--ink);overflow:hidden;padding:5vh 5vw;display:grid;grid-template-rows:auto 1fr auto;gap:2.5vh;box-sizing:border-box}.cms-title small,.cms-footer{font:800 clamp(9px,1.1vw,15px) var(--mono-font);letter-spacing:.14em;color:var(--primary)}.cms-title h1{font:900 clamp(42px,6.5vw,104px)/.82 var(--display-font);letter-spacing:-.065em;margin:8px 0 0}.cms-grid{display:grid;gap:2.2vw;align-items:center;min-height:0}.creator-growth-recap .cms-grid{grid-template-columns:1.25fr .8fr .8fr}.sponsorship-announcement .cms-grid{grid-template-columns:1fr;grid-template-rows:1fr 1fr}.publishing-workflow .cms-grid{grid-template-columns:1fr;grid-template-rows:repeat(3,1fr)}.cms-card{display:grid;place-items:center;min-height:0;height:100%;overflow:visible}.cms-card .nex-creator-module{transform:scale(var(--card-scale,.9))}.sponsorship-announcement .cms-card .nex-creator-module{--cm-w:470px;--cm-h:330px;transform:scale(.88)}.publishing-workflow .cms-card .nex-creator-module{--cm-w:470px;--cm-h:300px;transform:scale(.82)}.cms-footer{align-self:end}@media(max-aspect-ratio:1/1){.creator-module-scene{padding:5vh 5vw}.creator-growth-recap .cms-grid{grid-template-columns:1fr;grid-template-rows:1.2fr .8fr .8fr}.creator-growth-recap .cms-card .nex-creator-module{transform:scale(.72)}}''')
scene_html=lambda name,title,subtitle,w,h: f'''<!doctype html><html data-paper-style="clean-editorial"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../styles/tokens.css"><link rel="stylesheet" href="../styles/paper.css"><link rel="stylesheet" href="../styles/icons.css"><link rel="stylesheet" href="../styles/creator-icons.css"><link rel="stylesheet" href="../styles/creator-modules.css"><link rel="stylesheet" href="../styles/creator-module-scenes.css"><title>{title}</title></head><body><div class="creator-module-scene {name}" data-composition-id="{name}" data-start="0" data-duration="12" data-track-index="1" data-width="{w}" data-height="{h}"><header class="cms-title"><small>{subtitle}</small><h1>{title}</h1></header><main class="cms-grid"></main><footer class="cms-footer">NEXSTUDIO PAPER MOTION · BATCH 11</footer></div><script src="../vendor/gsap-compat.js"></script><script src="../runtime/theme.js"></script><script src="../runtime/motion-engine.js"></script><script src="../runtime/creator-icon-registry.js"></script><script src="../components/creator-icons.js"></script><script src="../runtime/creator-module-registry.js"></script><script src="../components/creator-modules.js"></script><script src="../runtime/creator-module-scenes.js"></script><script>NexCreatorModuleScenes.init('{name}')</script></body></html>'''
(root/'compositions/creator-growth-recap.html').write_text(scene_html('creator-growth-recap','GROWTH, EXPLAINED.','CREATOR GROWTH RECAP',1920,1080))
(root/'compositions/sponsorship-announcement.html').write_text(scene_html('sponsorship-announcement','A PARTNERSHIP WITH PURPOSE.','SPONSORSHIP ANNOUNCEMENT',1080,1080))
