scene_js=r'''window.NexCreatorModuleScenes=(()=>{function mount(host,id,cfg,scale=.9){const wrap=document.createElement('div');wrap.className='cms-card';wrap.style.setProperty('--card-scale',scale);const el=NexCreatorModules.create(id,cfg);wrap.append(el);host.append(wrap);const tl=NexCreatorModules.animate(el,{duration:2.1,energy:'medium'});return{wrap,el,tl}}
 function init(name){const root=document.querySelector('[data-composition-id]'),host=root.querySelector('.cms-grid');let cards=[];if(name==='creator-growth-recap'){NexTheme.applyPalette('warm');NexTheme.setStyle('clean-editorial');cards=[mount(host,'module.creator.engagement-summary.paper-01',{},.9),mount(host,'module.creator.subscriber-counter.paper-01',{},.86),mount(host,'module.creator.campaign-result.paper-01',{},.82)]}if(name==='sponsorship-announcement'){NexTheme.applyPalette('cobalt');NexTheme.setStyle('bold-paper-collage');cards=[mount(host,'module.creator.sponsorship-card.paper-01',{},.9),mount(host,'module.creator.brand-partnership.paper-01',{},.9)]}if(name==='publishing-workflow'){NexTheme.applyPalette('charcoal');NexTheme.setStyle('technical-notebook');cards=[mount(host,'module.creator.content-calendar.paper-01',{},.84),mount(host,'module.creator.publishing-checklist.paper-01',{},.84),mount(host,'module.creator.call-to-subscribe.paper-01',{},.84)]}
 const master=NexMotion.createTimeline({defaults:{ease:'power3.out'}});cards.forEach((c,i)=>{master.fromTo(c.wrap,{x:i%2?-55:55,y:28,opacity:0,rotation:i%2?-1.5:1.5},{x:0,y:0,opacity:1,rotation:0,duration:.65,ease:'back.out(1.4)'},.2+i*2.7);master.fromTo(c.wrap,{scale:.99},{scale:1.01,duration:1.1,ease:'sine.inOut',repeat:1,yoyo:true},1+i*2.7)});const baseSeek=master.seek.bind(master);master.seek=t=>{baseSeek(t);cards.forEach((c,i)=>c.tl.seek(Math.max(0,Math.min(c.tl.duration(),t-(.15+i*2.7)))));return master};master.duration(12);window.__timelines=window.__timelines||{};window.__timelines[name]=master;window.seekComposition=t=>master.seek(t);master.seek(0);return master}return{init}})();'''
(root/'runtime/creator-module-scenes.js').write_text(scene_js)
